import math

def spl(lw, d, barrier=False):
    loss = 20 * math.log10(d) + 11.0
    val = lw - loss
    if barrier:
        val -= 10.0
    return val

def sum_db(dbs):
    return 10 * math.log10(sum(10**(x/10.0) for x in dbs))

print('Testing distances for GEN (Lw=106):')
for d in [100, 150, 200, 250, 300]:
    print(f'd={d}: unshielded={spl(106, d, False):.2f} dB, shielded={spl(106, d, True):.2f} dB')

print('\nTesting distances for CTP (Lw=100):')
for d in [100, 150, 200, 250, 300]:
