"

python3 -c "
import math

def point_in_poly(x, y, poly):
    n = len(poly)
    inside = False
    p1x, p1y = poly[0]
    for i in range(n + 1):
        p2x, p2y = poly[i % n]
        if y > min(p1y, p2y):
            if y <= max(p1y, p2y):
                if x <= max(p1x, p2x):
                    if p1y != p2y:
                        xints = (y - p1y) * (p2x - p1x) / (p2y - p1y) + p1x
                    if p1x == p2x or x <= xints:
                        inside = not inside
        p1x, p1y = p2x, p2y
    return inside

def dist_pt_seg(px, py, ax, ay, bx, by):
    dx, dy = bx - ax, by - ay
    if dx == 0 and dy == 0:
        return math.hypot(px - ax, py - ay)
    t = max(0.0, min(1.0, ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy)))
    return math.hypot(px - (ax + t * dx), py - (ay + t * dy))

def dist_poly_poly(poly1, poly2):
    # Min distance between two polygons
    min_d = float('inf')
    for p in poly1:
        if point_in_poly(p[0], p[1], poly2): return 0.0
    for p in poly2:
        if point_in_poly(p[0], p[1], poly1): return 0.0
    n1, n2 = len(poly1), len(poly2)
    for i in range(n1):
        p1 = poly1[i]
        for j in range(n2):
            q1, q2 = poly2[j], poly2[(j+1)%n2]
            d = dist_pt_seg(p1[0], p1[1], q1[0], q1[1], q2[0], q2[1])
            if d < min_d: min_d = d
    for j in range(n2):
        p2 = poly2[j]
        for i in range(n1):
            q1, q2 = poly1[i], poly1[(i+1)%n1]
            d = dist_pt_seg(p2[0], p2[1], q1[0], q1[1], q2[0], q2[1])
            if d < min_d: min_d = d
    return min_d

wet1 = [[15, 100], [150, 90], [160, 170], [25, 180]]
wet2 = [[200, 60], [320, 55], [320, 150], [205, 160]]

# Test a DH_P1 footprint
dh1 = [[25, 25], [115, 25], [115, 75], [25, 75]]
print('dh1 dist to wet1:', dist_poly_poly(dh1, wet1))
print('dh1 dist to wet2:', dist_poly_poly(dh1, wet2))
"

